<template>
  <p class="note" :class="{ 'note--vide': note === null }">Note&nbsp;: {{ texte }}</p>
</template>

<script>
import { trouverJeu } from '../data/jeux';

// Badge de note à la fin de « Mon ressenti », lu dans src/data/jeux.js. Un tiret tant que la
// note n'est pas renseignée.
export default {
  name: 'NoteJeuComponent',
  computed: {
    note() {
      const jeu = trouverJeu(this.$route.path);
      return jeu && typeof jeu.note === 'number' ? jeu.note : null;
    },
    texte() {
      return this.note === null ? '–' : `${this.note}/10`;
    },
  },
};
</script>
