// Types de questions, dans l’ordre d’affichage de l’écran de réglage
export const TYPES = [
  { type: 'choix', libelle: 'QCM' },
  { type: 'vraifaux', libelle: 'Vrai ou faux' },
  { type: 'texte', libelle: 'Réponse à écrire' },
  { type: 'ordre', libelle: 'Remise en ordre' },
];

export const QUESTIONS = [
  ...QUESTIONS_QCM.map((q) => ({ type: 'choix', ...q })),
  ...QUESTIONS_VRAI_FAUX.map((q) => ({ type: 'vraifaux', ...q })),
  ...QUESTIONS_TEXTE.map((q) => ({ type: 'texte', ...q })),
  ...QUESTIONS_ORDRE.map((q) => ({ type: 'ordre', ...q })),
];

// Mélange de Fisher-Yates, avec un générateur de nombres injectable pour les tests
export function melanger(liste, aleatoire = Math.random) {
  const copie = liste.slice();
  for (let i = copie.length - 1; i > 0; i -= 1) {
    const j = Math.floor(aleatoire() * (i + 1));
    [copie[i], copie[j]] = [copie[j], copie[i]];
  }
  return copie;
}

// Niveaux de difficulté, dans l’ordre d’affichage de l’écran de réglage
export const NIVEAUX = [
  { points: 1, libelle: '1 pt · facile' },
  { points: 2, libelle: '2 pts · moyen' },
  { points: 3, libelle: '3 pts · difficile' },
];

// Nombre de questions par valeur d’un champ (thème ou type)
function compterPar(champ) {
  const compte = {};
  QUESTIONS.forEach((q) => {
    compte[q[champ]] = (compte[q[champ]] || 0) + 1;
  });
  return compte;
}

// Thèmes présents dans le réservoir, du plus fourni au moins fourni, avec leur nombre de questions
export const THEMES = Object.entries(compterPar('theme'))
  .map(([nom, nombre]) => ({ nom, nombre }))
  .sort((a, b) => b.nombre - a.nombre || a.nom.localeCompare(b.nom, 'fr'));

// Nombre de questions de chaque type
export const NOMBRE_PAR_TYPE = compterPar('type');

// Sous-ensemble du réservoir correspondant aux réglages ; une liste vide signifie « pas de filtre »
export function filtrerQuestions({ themes = [], points = [], types = [] } = {}, reservoir = QUESTIONS) {
  return reservoir.filter(
    (q) =>
      (!themes.length || themes.includes(q.theme)) &&
      (!points.length || points.includes(q.points)) &&
      (!types.length || types.includes(q.type))
  );
}

// Répartitions (nombre de questions à 1, 2 et 3 points) réalisables avec `nombre` questions du
// réservoir, chacune avec le total de points qu’elle donne
function repartitionsPossibles(reservoir, nombre) {
  const stock = { 1: 0, 2: 0, 3: 0 };
  reservoir.forEach((q) => {
    stock[q.points] += 1;
  });
  const repartitions = [];
  for (let c = 0; c <= Math.min(stock[3], nombre); c += 1) {
    for (let b = 0; b <= Math.min(stock[2], nombre - c); b += 1) {
      const a = nombre - b - c;
      if (a <= stock[1]) repartitions.push({ 1: a, 2: b, 3: c, total: a + 2 * b + 3 * c });
    }
  }
  return repartitions;
}

// Totaux de points atteignables avec `nombre` questions du réservoir : bornes et liste triée
export function totauxPossibles(reservoir, nombre) {
  const totaux = [...new Set(repartitionsPossibles(reservoir, nombre).map((r) => r.total))].sort(
    (a, b) => a - b
  );
  return { min: totaux[0] ?? 0, max: totaux[totaux.length - 1] ?? 0, possibles: totaux };
}

// Prépare une question tirée pour l’affichage : identifiant, réponses mélangées, ordre mélangé
function preparer(question, index, aleatoire, prochainId) {
  const base = { ...question, id: `q${index + 1}` };
  if (question.type === 'choix') {
    return {
      ...base,
      options: melanger(question.choix, aleatoire).map((valeur) => ({ id: prochainId(), valeur, libelle: valeur })),
    };
  }
  if (question.type === 'vraifaux') {
    return {
      ...base,
      options: [
        { id: prochainId(), valeur: true, libelle: 'Vrai' },
        { id: prochainId(), valeur: false, libelle: 'Faux' },
      ],
    };
  }
  if (question.type === 'ordre') {
    let ordreAffiche = melanger(question.elements, aleatoire);
    // Jamais le bon ordre d’entrée de jeu : on décale d’un cran si le mélange n’a rien changé
    if (ordreAffiche.every((element, i) => element === question.elements[i])) {
      ordreAffiche = [...ordreAffiche.slice(1), ordreAffiche[0]];
    }
    return { ...base, ordreAffiche };
  }
  return base;
}

// Tire `nombre` questions distinctes, prêtes à l’affichage. Réglages facultatifs : `themes`,
// `points` et `types` filtrent le réservoir, `totalPoints` impose la somme des points (la
// répartition entre niveaux est alors tirée au hasard parmi celles qui conviennent).
// Renvoie une liste vide si aucun tirage ne respecte les réglages.
export function tirerQuestions(nombre, aleatoire = Math.random, reglages = {}) {
  const reservoir = filtrerQuestions(reglages);
  if (!reservoir.length) return [];
  const total = Math.max(1, Math.min(nombre, reservoir.length));

  let choisies;
  if (reglages.totalPoints == null) {
    choisies = melanger(reservoir, aleatoire).slice(0, total);
  } else {
    const candidates = repartitionsPossibles(reservoir, total).filter((r) => r.total === reglages.totalPoints);
    if (!candidates.length) return [];
    const repartition = candidates[Math.floor(aleatoire() * candidates.length)];
    choisies = melanger(
      [1, 2, 3].flatMap((p) =>
        melanger(
          reservoir.filter((q) => q.points === p),
          aleatoire
        ).slice(0, repartition[p])
      ),
      aleatoire
    );
  }

  let compteur = 0;
  const prochainId = () => `radio${++compteur}`;
  return choisies.map((question, index) => preparer(question, index, aleatoire, prochainId));
}

// Forme comparable d’une réponse écrite : minuscules, sans accents, sans ponctuation ni espaces
export function normaliserTexte(valeur) {
  return String(valeur ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

// Vrai si `reponse` (ce que l’utilisateur a donné) est la bonne réponse de la question
export function estBonneReponse(question, reponse) {
  if (reponse === null || reponse === undefined || reponse === '') return false;
  switch (question.type) {
    case 'texte':
      return question.reponses.some((r) => normaliserTexte(r) === normaliserTexte(reponse));
    case 'ordre':
      return question.elements.every((element, i) => reponse[i] === element);
    default:
      return reponse === question.reponse;
  }
}

// Texte lisible d’une réponse donnée (celle de l’utilisateur), « Aucun » si rien n’a été répondu
export function libelleReponse(question, reponse) {
  if (reponse === null || reponse === undefined || reponse === '') return 'Aucun';
  if (question.type === 'vraifaux') return reponse ? 'Vrai' : 'Faux';
  if (question.type === 'ordre') return reponse.join(' → ');
  return String(reponse);
}

// Texte lisible de la bonne réponse d’une question
export function libelleBonneReponse(question) {
  switch (question.type) {
    case 'texte':
      return question.reponses[0];
    case 'ordre':
      return question.elements.join(' → ');
    default:
      return libelleReponse(question, question.reponse);
  }
}

