// Sections d'une page de review ou de Let's Play, lues directement dans le document.
//
// Les menus de ces pages se construisent à partir de ce qui est réellement affiché, plutôt que
// d'une liste figée : une page sans section Histoire n'affiche pas de lien mort, et une section
// ajoutée (un DLC, par exemple) apparaît dans le menu sans autre changement.
//
// Le libellé du lien est le titre de la section. Une section peut en proposer un plus court pour
// le menu avec l'attribut `data-menu`, par exemple `data-menu="DLC"`.

export function lireSectionsDeLaPage(racine = typeof document !== 'undefined' ? document : null) {
  if (!racine || typeof racine.querySelectorAll !== 'function') return [];
  return Array.from(racine.querySelectorAll('main section[id]'))
    .map((section) => {
      const titreSection = section.querySelector('h2');
      const titre = (section.dataset.menu || (titreSection && titreSection.textContent) || '').trim();
      return { id: section.id, titre };
    })
    .filter((section) => section.id && section.titre);
}

export default lireSectionsDeLaPage;
