<template>
  <div class="quiz">
    <!-- Écran de réglage. Seul le nombre de questions est visible d'emblée : c'est le seul choix
         nécessaire pour lancer une partie. Thèmes, types, difficulté et objectif de points sont
         rangés derrière le bouton « Filtres », qui indique combien sont actifs. -->
    <div v-if="!questionnaireGenere" class="bordure-texte quiz__reglage">
      <h2>Quiz Geek Zone</h2>
      <p class="quiz__intro">
        {{ nombreTotalQuestions }} questions dans le réservoir, tirées au hasard à chaque partie.
      </p>

      <div class="quiz__bloc">
        <h3 class="quiz__bloc-titre">Nombre de questions</h3>
        <div class="quiz__choix" role="group" aria-label="Nombre de questions">
          <button
            v-for="nombre in nombresAffiches"
            :key="nombre"
            type="button"
            class="quiz__nombre"
            :class="{ 'quiz__nombre--choisi': nombreEffectif === nombre }"
            @click="nombreChoisi = nombre"
          >
            {{ nombre === nombreDisponible ? `Toutes (${nombre})` : nombre }}
          </button>
        </div>
      </div>

      <button
        type="button"
        class="filtres-bouton quiz__filtres-bouton"
        :class="{ 'filtres-bouton--actif': nombreFiltresActifs > 0 }"
        :aria-expanded="filtresOuverts ? 'true' : 'false'"
        aria-controls="quiz-filtres"
        @click="basculerFiltres"
      >
        <svg viewBox="0 0 24 24" aria-hidden="true">
          <path d="M3 5h18l-7 8v5l-4 2v-7L3 5z" />
        </svg>
        <span>{{ libelleBoutonFiltres }}</span>
      </button>

      <p v-if="nombreFiltresActifs" class="quiz__detail quiz__disponibles">
        {{ messageDisponibles }}
      </p>

      <div v-show="filtresOuverts" id="quiz-filtres" class="quiz__filtres-panneau">
        <div class="quiz__bloc">
          <h3 class="quiz__bloc-titre">Thèmes</h3>
          <div class="quiz__choix" role="group" aria-label="Thèmes">
            <button
              type="button"
              class="quiz__nombre"
              :class="{ 'quiz__nombre--choisi': !themesChoisis.length }"
              @click="themesChoisis = []"
            >
              Tous
            </button>
            <button
              v-for="theme in themes"
              :key="theme.nom"
              type="button"
              class="quiz__nombre quiz__theme-bouton"
              :class="{ 'quiz__nombre--choisi': themesChoisis.includes(theme.nom) }"
              :aria-pressed="themesChoisis.includes(theme.nom)"
              @click="basculer(themesChoisis, theme.nom)"
            >
              {{ theme.nom }}<small>{{ theme.nombre }}</small>
            </button>
          </div>
        </div>

        <div class="quiz__bloc">
          <h3 class="quiz__bloc-titre">Types de questions</h3>
          <div class="quiz__choix" role="group" aria-label="Types de questions">
            <button
              type="button"
              class="quiz__nombre"
              :class="{ 'quiz__nombre--choisi': !typesChoisis.length }"
              @click="typesChoisis = []"
            >
              Tous
            </button>
            <button
              v-for="type in types"
              :key="type.type"
              type="button"
              class="quiz__nombre quiz__type-bouton"
              :class="{ 'quiz__nombre--choisi': typesChoisis.includes(type.type) }"
              :aria-pressed="typesChoisis.includes(type.type)"
              @click="basculer(typesChoisis, type.type)"
            >
              {{ type.libelle }}<small>{{ type.nombre }}</small>
            </button>
          </div>
        </div>

        <div class="quiz__bloc">
          <h3 class="quiz__bloc-titre">Difficulté</h3>
          <div class="quiz__choix" role="group" aria-label="Difficulté">
            <button
              type="button"
              class="quiz__nombre"
              :class="{ 'quiz__nombre--choisi': !pointsChoisis.length }"
              @click="pointsChoisis = []"
            >
              Toutes
            </button>
            <button
              v-for="niveau in niveaux"
              :key="niveau.points"
              type="button"
              class="quiz__nombre quiz__niveau-bouton"
              :class="{ 'quiz__nombre--choisi': pointsChoisis.includes(niveau.points) }"
              :aria-pressed="pointsChoisis.includes(niveau.points)"
              @click="basculer(pointsChoisis, niveau.points)"
            >
              {{ niveau.libelle }}
            </button>
          </div>
        </div>

        <div class="quiz__bloc">
          <h3 class="quiz__bloc-titre">Total de points</h3>
          <div class="quiz__choix" role="group" aria-label="Total de points">
            <button
              type="button"
              class="quiz__nombre"
              :class="{ 'quiz__nombre--choisi': !totalImpose }"
              @click="totalImpose = false"
            >
              Libre
            </button>
            <button
              type="button"
              class="quiz__nombre"
              :class="{ 'quiz__nombre--choisi': totalImpose }"
              :disabled="!nombreDisponible"
              @click="imposerTotal"
            >
              Imposé
            </button>
            <label v-if="totalImpose" class="quiz__total">
              <span>Objectif</span>
              <input
                v-model.number="totalVoulu"
                type="number"
                :min="plageTotaux.min"
                :max="plageTotaux.max"
                step="1"
                aria-label="Total de points voulu"
              />
              <span>pts</span>
            </label>
          </div>
          <p class="quiz__detail quiz__message-total" :class="{ 'quiz__detail--erreur': !totalValide }">
            {{ messageTotal }}
          </p>
        </div>

        <p class="quiz__detail quiz__legende-points">
          Questions faciles à 1 point, moyennes à 2, difficiles à 3. Les réponses sont corrigées à la
          fin.
        </p>
      </div>

      <button class="quiz__generer" :disabled="!peutGenerer" @click="genererQuestionnaire()">
        Générer le questionnaire
      </button>
    </div>

    <template v-else>
      <div class="bordure-texte quiz__entete">
        <p class="quiz__intro">
          {{ questions.length }} questions, <strong>{{ totalPoints }} points</strong> à gagner.
        </p>
        <p v-if="resumeReglages" class="quiz__resume">{{ resumeReglages }}</p>
        <!-- Avant correction : avancement des réponses ; après : le score obtenu -->
        <div
          class="quiz__progression"
          :class="{ 'quiz__progression--score': corrige }"
          role="progressbar"
          :aria-valuenow="corrige ? score : nombreRepondues"
          aria-valuemin="0"
          :aria-valuemax="corrige ? totalPoints : questions.length"
        >
          <span :style="{ width: pourcentageBarre + '%' }"></span>
        </div>
        <p class="quiz__compteur">{{ texteCompteur }}</p>
      </div>

      <div class="quiz__grille">
        <div
          v-for="(question, index) in questions"
          :key="question.id"
          :id="`carte-${question.id}`"
          class="bordure-texte quiz__question"
          :class="[
            `quiz__question--${question.type}`,
            {
              'quiz__question--repondue': !corrige && estRepondue(question),
              'quiz__question--juste': corrige && estBonneReponse(question),
              'quiz__question--faux': corrige && !estBonneReponse(question),
              'quiz__question--visee': carteVisee === question.id,
            },
          ]"
          role="group"
          :aria-labelledby="`${question.id}-legende`"
        >
          <!-- Première rangée de la carte : légende (posée sur la bordure) et texte de la question -->
          <div class="quiz__intitule">
            <p class="quiz__legende" :id="`${question.id}-legende`">
              <span class="quiz__legende-fond">
                Question {{ index + 1 }}
                <span class="quiz__points">{{ question.points }} {{ question.points > 1 ? 'pts' : 'pt' }}</span>
                <span class="quiz__theme">{{ question.theme }}</span>
              </span>
            </p>
            <p class="quiz__texte">{{ question.texte }}</p>
          </div>

          <!-- Seconde rangée : la zone de réponse, selon le type -->
          <div class="quiz__reponse">
            <!-- QCM et vrai ou faux : boutons radio -->
            <div
              v-if="question.options"
              class="quiz__options"
              :class="{ 'quiz__options--ligne': question.type === 'vraifaux' }"
            >
              <label
                v-for="option in question.options"
                :key="option.id"
                :for="option.id"
                class="quiz__option"
                :class="classeOption(question, option.valeur)"
              >
                <input
                  type="radio"
                  :id="option.id"
                  :name="question.id"
                  :value="option.valeur"
                  v-model="userAnswers[question.id]"
                  :disabled="corrige"
                />
                <span>{{ option.libelle }}</span>
              </label>
            </div>

            <!-- Réponse à écrire : un champ texte -->
            <div v-else-if="question.type === 'texte'" class="quiz__saisie" :class="classeSaisie(question)">
              <input
                v-model.trim="userAnswers[question.id]"
                type="text"
                autocomplete="off"
                placeholder="Écris ta réponse"
                :aria-label="question.texte"
                :disabled="corrige"
              />
            </div>

            <!-- Remise en ordre : une liste que l’on réordonne avec des flèches -->
            <ol v-else-if="question.type === 'ordre'" class="quiz__ordre">
              <li
                v-for="(element, position) in ordreCourant(question)"
                :key="element"
                class="quiz__ordre-item"
                :class="classeElement(question, element, position)"
              >
                <span class="quiz__ordre-rang">{{ position + 1 }}</span>
                <span class="quiz__ordre-nom">{{ element }}</span>
                <span class="quiz__ordre-boutons">
                  <button
                    type="button"
                    class="quiz__ordre-bouton"
                    :disabled="corrige || position === 0"
                    :aria-label="`Monter ${element}`"
                    @click="deplacer(question, position, -1)"
                  >
                    ▲
                  </button>
                  <button
                    type="button"
                    class="quiz__ordre-bouton"
                    :disabled="corrige || position === question.elements.length - 1"
                    :aria-label="`Descendre ${element}`"
                    @click="deplacer(question, position, 1)"
                  >
                    ▼
                  </button>
                </span>
              </li>
            </ol>

            <p v-if="corrige && !estBonneReponse(question)" class="quiz__attendu">
              {{ question.type === 'ordre' ? 'Bon ordre' : 'Réponse' }}&nbsp;: {{ libelleBonneReponse(question) }}
            </p>
          </div>
        </div>
      </div>

      <!-- Résultats sous les questions plutôt que dans une fenêtre : la correction de chaque carte
           reste visible, et chaque erreur ramène directement à sa question -->
      <div v-if="corrige" id="quiz-resultat" class="bordure-texte quiz__resultat" role="status">
        <h2 class="titre-carte">Résultats</h2>
        <p class="quiz__resultat-score">Score&nbsp;: {{ score }}/{{ totalPoints }}</p>
        <p class="quiz__resultat-verdict">{{ verdict }}</p>
        <p v-if="!incorrectAnswers.length" class="quiz__resultat-parfait">Sans faute, bravo&nbsp;!</p>
        <template v-else>
          <p class="quiz__resultat-rate">{{ texteErreurs }}</p>
          <ul class="quiz__resultat-liste">
            <li v-for="erreur in incorrectAnswers" :key="erreur.id">
              <button type="button" class="quiz__resultat-lien" @click="allerALaQuestion(erreur.id)">
                <span class="quiz__resultat-numero">Question {{ erreur.numero }}</span>
                <span class="quiz__resultat-texte">{{ erreur.questionText }}</span>
                <span class="quiz__resultat-bonne">Réponse&nbsp;: {{ erreur.correctAnswer }}</span>
              </button>
            </li>
          </ul>
        </template>
      </div>

      <div class="quiz__actions">
        <button v-if="!corrige" class="confirm-btn" @click="showResults">Confirmer</button>
        <button v-if="corrige" type="button" class="quiz__rejouer" @click="rejouer">
          Nouveau questionnaire
        </button>
        <button type="button" class="quiz__changer" @click="retourReglage">Changer les réglages</button>
      </div>
    </template>
  </div>
</template>

<script>
import {
  QUESTIONS,
  THEMES,
  TYPES,
  NOMBRE_PAR_TYPE,
  NIVEAUX,
  filtrerQuestions,
  totauxPossibles,
  tirerQuestions,
  estBonneReponse,
  libelleReponse,
  libelleBonneReponse,
  NOMBRES_PROPOSES,
  NOMBRE_PAR_DEFAUT,
} from '../data/questions';

// Espace insécable avant les deux-points, comme partout ailleurs sur le site
const INSECABLE = String.fromCharCode(160);

// Ouverture du panneau de réglages, retenue le temps de la visite comme sur la page Review
const CLE_PANNEAU = 'geekzone-quiz-filtres-ouverts';

function lirePanneauOuvert() {
  try {
    return sessionStorage.getItem(CLE_PANNEAU) === '1';
  } catch (e) {
    return false;
  }
}

export default {
  name: 'QuestionComponent',
  data() {
    return {
      nombreTotalQuestions: QUESTIONS.length,
      themes: THEMES,
      types: TYPES.map((t) => ({ ...t, nombre: NOMBRE_PAR_TYPE[t.type] || 0 })),
      niveaux: NIVEAUX,
      themesChoisis: [],
      typesChoisis: [],
      pointsChoisis: [],
      nombreChoisi: NOMBRE_PAR_DEFAUT,
      totalImpose: false,
      totalVoulu: null,
      filtresOuverts: lirePanneauOuvert(),
      questionnaireGenere: false,
      questions: [],
      userAnswers: {},
      score: 0,
      totalPoints: 0,
      incorrectAnswers: [],
      corrige: false,
      // Question mise en avant après un clic dans la liste des erreurs
      carteVisee: null,
      minuteurVisee: null,
    };
  },
  beforeUnmount() {
    clearTimeout(this.minuteurVisee);
  },
  computed: {
    reglages() {
      return { themes: this.themesChoisis, points: this.pointsChoisis, types: this.typesChoisis };
    },
    questionsDisponibles() {
      return filtrerQuestions(this.reglages);
    },
    nombreDisponible() {
      return this.questionsDisponibles.length;
    },
    // Les nombres proposés qui restent possibles avec ces filtres, plus « Toutes »
    nombresAffiches() {
      if (!this.nombreDisponible) return [];
      return [...NOMBRES_PROPOSES.filter((n) => n < this.nombreDisponible), this.nombreDisponible];
    },
    // Le nombre voulu, ramené à ce que le réservoir filtré permet
    nombreEffectif() {
      return Math.min(this.nombreChoisi, this.nombreDisponible);
    },
    plageTotaux() {
      return totauxPossibles(this.questionsDisponibles, this.nombreEffectif);
    },
    totalValide() {
      return !this.totalImpose || this.plageTotaux.possibles.includes(this.totalVoulu);
    },
    peutGenerer() {
      return this.nombreDisponible > 0 && this.totalValide;
    },
    // Filtres qui s'écartent du tirage par défaut, comptés sur le bouton pour qu'un filtre
    // laissé actif ne passe pas inaperçu quand le panneau est replié
    nombreFiltresActifs() {
      return (
        this.themesChoisis.length +
        this.typesChoisis.length +
        this.pointsChoisis.length +
        (this.totalImpose ? 1 : 0)
      );
    },
    libelleBoutonFiltres() {
      return this.nombreFiltresActifs ? `Filtres (${this.nombreFiltresActifs})` : 'Filtres';
    },
    messageDisponibles() {
      if (!this.nombreDisponible) return 'Aucune question ne correspond à ces filtres.';
      if (this.nombreDisponible === 1) return 'Une seule question correspond à ces filtres.';
      return `${this.nombreDisponible} questions correspondent à ces filtres.`;
    },
    messageTotal() {
      const { min, max, possibles } = this.plageTotaux;
      if (!this.nombreDisponible) return '';
      const plage =
        min === max
          ? `${this.nombreEffectif} questions font forcément ${min} points.`
          : `${this.nombreEffectif} questions font entre ${min} et ${max} points.`;
      if (!this.totalImpose) return plage;
      if (this.totalValide) return `${plage} Le tirage s’adaptera pour totaliser ${this.totalVoulu} points.`;
      if (Number.isInteger(this.totalVoulu) && this.totalVoulu >= min && this.totalVoulu <= max) {
        const proche = possibles.reduce((meilleur, t) =>
          Math.abs(t - this.totalVoulu) < Math.abs(meilleur - this.totalVoulu) ? t : meilleur
        );
        return `${plage} ${this.totalVoulu} points n’est pas atteignable avec ces niveaux, essaie ${proche}.`;
      }
      return `${plage} Choisis un total dans cette fourchette.`;
    },
    // Rappel des filtres et de l'objectif au-dessus du questionnaire
    resumeReglages() {
      const parts = [];
      if (this.themesChoisis.length) parts.push(`Thèmes : ${this.themesChoisis.join(', ')}`);
      if (this.typesChoisis.length) {
        parts.push(`Types : ${this.typesChoisis.map((t) => this.libelleType(t)).join(', ')}`);
      }
      if (this.pointsChoisis.length) {
        parts.push(`Difficulté : ${this.pointsChoisis.map((p) => `${p} pt${p > 1 ? 's' : ''}`).join(', ')}`);
      }
      if (this.totalImpose) parts.push(`Objectif : ${this.totalVoulu} points`);
      return parts.join(' · ');
    },
    nombreRepondues() {
      return this.questions.filter((q) => this.estRepondue(q)).length;
    },
    pourcentageRepondu() {
      if (!this.questions.length) return 0;
      return Math.round((this.nombreRepondues / this.questions.length) * 100);
    },
    // La barre montre l'avancement avant la correction, puis la part des points obtenus
    pourcentageBarre() {
      if (!this.corrige) return this.pourcentageRepondu;
      return this.totalPoints ? Math.round((this.score / this.totalPoints) * 100) : 0;
    },
    texteCompteur() {
      if (this.corrige) return `Score${INSECABLE}: ${this.score} / ${this.totalPoints} points`;
      return `${this.nombreRepondues} / ${this.questions.length} réponses`;
    },
    texteErreurs() {
      if (this.incorrectAnswers.length === 1) return 'Une question ratée, clique dessus pour la revoir :';
      return `${this.incorrectAnswers.length} questions ratées, clique sur l’une d’elles pour la revoir :`;
    },
    verdict() {
      const ratio = this.totalPoints ? this.score / this.totalPoints : 0;
      if (ratio === 1) return 'Score parfait, un vrai geek.';
      if (ratio >= 0.7) return 'Très bon score, il ne manque pas grand-chose.';
      if (ratio >= 0.4) return 'Pas mal, mais il y a de la marge.';
      return 'Aïe. Une petite révision sur la page Review et on recommence ?';
    },
  },
  methods: {
    // Ajoute ou retire une valeur d'une liste de filtres (thèmes, types ou niveaux)
    basculer(liste, valeur) {
      const index = liste.indexOf(valeur);
      if (index === -1) liste.push(valeur);
      else liste.splice(index, 1);
    },
    basculerFiltres() {
      this.filtresOuverts = !this.filtresOuverts;
      try {
        sessionStorage.setItem(CLE_PANNEAU, this.filtresOuverts ? '1' : '0');
      } catch (e) {
        // stockage indisponible : le panneau ne sera juste pas mémorisé
      }
    },
    libelleType(type) {
      const trouve = TYPES.find((t) => t.type === type);
      return trouve ? trouve.libelle : type;
    },
    // Active l'objectif de points, en proposant le milieu de la fourchette si rien n'est saisi
    imposerTotal() {
      this.totalImpose = true;
      if (!this.plageTotaux.possibles.includes(this.totalVoulu)) {
        const { possibles } = this.plageTotaux;
        this.totalVoulu = possibles[Math.floor(possibles.length / 2)] ?? null;
      }
    },
    // Tire un nouveau questionnaire selon les réglages ; `aleatoire` permet un tirage reproductible
    genererQuestionnaire(aleatoire = Math.random) {
      // Appelée depuis un clic, la méthode reçoit l'événement : on l'ignore
      const tirage = typeof aleatoire === 'function' ? aleatoire : Math.random;
      if (!this.peutGenerer) return;
      const questions = tirerQuestions(this.nombreEffectif, tirage, {
        ...this.reglages,
        totalPoints: this.totalImpose ? this.totalVoulu : null,
      });
      if (!questions.length) return;
      this.questions = questions;
      this.userAnswers = Object.fromEntries(this.questions.map((q) => [q.id, null]));
      this.totalPoints = this.questions.reduce((total, q) => total + q.points, 0);
      this.score = 0;
      this.incorrectAnswers = [];
      this.corrige = false;
      this.carteVisee = null;
      this.questionnaireGenere = true;
    },
    // Une question compte comme répondue dès qu'elle a une valeur (« Faux » compris)
    estRepondue(question) {
      const reponse = this.userAnswers[question.id];
      return reponse !== null && reponse !== undefined && reponse !== '';
    },
    estBonneReponse(question) {
      return estBonneReponse(question, this.userAnswers[question.id]);
    },
    libelleBonneReponse(question) {
      return libelleBonneReponse(question);
    },
    // Remise en ordre : l'ordre affiché tant que l'utilisateur n'a rien déplacé, puis le sien
    ordreCourant(question) {
      return this.userAnswers[question.id] || question.ordreAffiche;
    },
    deplacer(question, position, sens) {
      if (this.corrige) return;
      const ordre = this.ordreCourant(question).slice();
      const cible = position + sens;
      if (cible < 0 || cible >= ordre.length) return;
      [ordre[position], ordre[cible]] = [ordre[cible], ordre[position]];
      this.userAnswers[question.id] = ordre;
    },
    showResults() {
      this.score = 0;
      this.incorrectAnswers = [];

      this.questions.forEach((question, index) => {
        const reponse = this.userAnswers[question.id];
        if (estBonneReponse(question, reponse)) {
          this.score += question.points;
        } else {
          this.incorrectAnswers.push({
            id: question.id,
            numero: index + 1,
            questionText: question.texte,
            userAnswer: libelleReponse(question, reponse),
            correctAnswer: libelleBonneReponse(question),
          });
        }
      });
      this.corrige = true;
      this.carteVisee = null;
      // Le panneau de résultats apparaît là où était le bouton : on l'amène sous les yeux
      this.$nextTick(() => this.amenerEnVue('quiz-resultat'));
    },
    // Ramène une question à l'écran et la met brièvement en avant
    allerALaQuestion(id) {
      if (!this.amenerEnVue(`carte-${id}`)) return;
      this.carteVisee = id;
      clearTimeout(this.minuteurVisee);
      this.minuteurVisee = setTimeout(() => {
        this.carteVisee = null;
      }, 1600);
    },
    // scrollIntoView n'existe pas partout (jsdom) : on ne fait rien plutôt que d'échouer
    amenerEnVue(id) {
      const element = typeof document !== 'undefined' && document.getElementById(id);
      if (!element) return false;
      if (typeof element.scrollIntoView === 'function') {
        const reduit = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        element.scrollIntoView({ behavior: reduit ? 'auto' : 'smooth', block: 'center' });
      }
      return true;
    },
    rejouer() {
      this.genererQuestionnaire();
      window.scrollTo({ top: 0 });
    },
    // Retour à l'écran de réglage ; les réglages sont conservés
    retourReglage() {
      this.questionnaireGenere = false;
      this.questions = [];
      this.userAnswers = {};
      this.corrige = false;
      this.carteVisee = null;
    },
    // Après correction : la bonne réponse en vert, un mauvais choix en rouge
    classeOption(question, valeur) {
      const choisie = this.userAnswers[question.id] === valeur;
      if (!this.corrige) return { 'quiz__option--choisie': choisie };
      return {
        'quiz__option--bonne': valeur === question.reponse,
        'quiz__option--fausse': choisie && valeur !== question.reponse,
      };
    },
    classeSaisie(question) {
      if (!this.corrige) return {};
      const bonne = this.estBonneReponse(question);
      return { 'quiz__saisie--bonne': bonne, 'quiz__saisie--fausse': !bonne };
    },
    // Après correction : chaque élément en vert s'il est à la bonne place, en rouge sinon
    classeElement(question, element, position) {
      if (!this.corrige) return {};
      const bon = question.elements[position] === element;
      return { 'quiz__ordre-item--bon': bon, 'quiz__ordre-item--mauvais': !bon };
    },
  },
};
</script>
