<template>
  <div class="filtres">
    <label class="filtres__champ">
      <span class="filtres__libelle">Trier par</span>
      <select class="filtres__select" :value="tri" @change="$emit('update:tri', $event.target.value)">
        <option v-for="option in tris" :key="option.cle" :value="option.cle">{{ option.libelle }}</option>
      </select>
    </label>
    <label v-for="filtre in filtresVisibles" :key="filtre.cle" class="filtres__champ">
      <span class="filtres__libelle">{{ filtre.libelle }}</span>
      <select
        class="filtres__select"
        :value="filtres[filtre.cle]"
        @change="changer(filtre.cle, $event.target.value)"
      >
        <option value="">{{ filtre.tous }}</option>
        <option v-for="valeur in options[filtre.cle]" :key="valeur" :value="valeur">
          {{ valeur }}
        </option>
      </select>
    </label>
    <button v-if="actifs" type="button" class="filtres__reset" @click="$emit('reinitialiser')">
      Réinitialiser
    </button>
  </div>
</template>

<script>
import { FILTRES, TRIS } from '../mixins/filtreJeux';

// Barre de filtres des listes Review et Let's Play : un menu de tri, puis un menu par filtre.
// Un filtre qui n'aurait qu'une seule valeur possible parmi les jeux de la page est masqué.
export default {
  name: 'FiltresJeuxComponent',
  props: {
    filtres: { type: Object, required: true },
    options: { type: Object, required: true },
    tri: { type: String, default: '' },
  },
  emits: ['update:filtres', 'update:tri', 'reinitialiser'],
  data() {
    return { tris: TRIS };
  },
  computed: {
    filtresVisibles() {
      return FILTRES.filter((f) => (this.options[f.cle] || []).length > 1);
    },
    actifs() {
      return Boolean(this.tri) || Object.values(this.filtres).some(Boolean);
    },
  },
  methods: {
    changer(cle, valeur) {
      this.$emit('update:filtres', { ...this.filtres, [cle]: valeur });
    },
  },
};
</script>
