import { createApp } from 'vue';
import App from './App.vue';
import router from './router';
import FicheJeu from './components/FicheJeuComponent.vue';
import NoteJeu from './components/NoteJeuComponent.vue';

const app = createApp(App);
app.use(router);
// Blocs communs aux pages de review et de Let's Play, alimentés par src/data/jeux.js
app.component('FicheJeu', FicheJeu);
app.component('NoteJeu', NoteJeu);
app.mount('#app');
