// Recherche et filtres des listes Review et Let's Play.
//
// - La recherche texte porte sur le titre affiché ET sur les attributs du jeu (src/data/jeux.js) :
//   taper « tarsier » trouve REANIMAL, « remake » trouve tous les remakes, « 2024 » les sorties 2024.
// - Les accents et la casse sont ignorés : « millenaire » trouve « Millénaire ».
// - Les filtres (genre, plateforme, type de jeu, éditeur, joueurs) se cumulent avec la recherche.
// - Un tri (date de review, date de sortie, titre, note) réordonne les cartes via CSS `order`.
//
// Le composant qui utilise ce mixin définit `typeJeux` ('review' ou 'letsplay') dans ses data,
// et appelle matches(nomAffiche, slug) dans le v-show de chaque carte.

import { jeux, trouverJeu } from '../data/jeux';

export const FILTRES = [
  { cle: 'genre', libelle: 'Genre', tous: 'Tous les genres' },
  { cle: 'plateformes', libelle: 'Plateforme', tous: 'Toutes les plateformes' },
  { cle: 'typeDeJeu', libelle: 'Type', tous: 'Tous les types' },
  { cle: 'editeur', libelle: 'Éditeur', tous: 'Tous les éditeurs' },
  { cle: 'joueurs', libelle: 'Joueurs', tous: 'Tous' },
];

export function filtresVides() {
  return Object.fromEntries(FILTRES.map((f) => [f.cle, '']));
}

// Minuscules, sans accents, espaces réduits
export function normaliser(texte) {
  return String(texte || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    // Les deux apostrophes se valent : taper « luigi's » retrouve « Luigi’s »
    .replace(/[’ʼ]/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

// Tout le texte dans lequel la recherche peut trouver un jeu
export function texteRecherchable(jeu) {
  if (!jeu) return '';
  const annee = jeu.dateSortie ? jeu.dateSortie.slice(0, 4) : '';
  return normaliser(
    [
      jeu.titre,
      ...(jeu.genre || []),
      ...(jeu.plateformes || []),
      jeu.editeur,
      jeu.developpeur,
      jeu.typeDeJeu,
      jeu.joueurs ? `${jeu.joueurs} joueurs` : '',
      annee,
    ].join(' ')
  );
}

// Valeurs disponibles pour chaque filtre, parmi les jeux du type demandé
export function optionsPour(typeJeux) {
  const liste = jeux.filter((jeu) => jeu.type === typeJeux);
  const options = {};
  FILTRES.forEach(({ cle }) => {
    const valeurs = new Set();
    liste.forEach((jeu) => {
      const valeur = jeu[cle];
      if (Array.isArray(valeur)) valeur.forEach((v) => v && valeurs.add(v));
      else if (valeur) valeurs.add(valeur);
    });
    options[cle] = [...valeurs].sort((a, b) => a.localeCompare(b, 'fr'));
  });
  return options;
}

export function correspondAuxFiltres(jeu, filtres) {
  return FILTRES.every(({ cle }) => {
    const voulu = filtres[cle];
    if (!voulu) return true;
    if (!jeu) return false;
    const valeur = jeu[cle];
    return Array.isArray(valeur) ? valeur.includes(voulu) : valeur === voulu;
  });
}

// Ordres de tri proposés dans le panneau de filtres. Les cartes restent dans l'ordre du code :
// c'est la propriété CSS `order` de la grille qui les réordonne.
export const TRIS = [
  { cle: '', libelle: 'Ordre du site' },
  { cle: 'review-recente', libelle: 'Review la plus récente' },
  { cle: 'review-ancienne', libelle: 'Review la plus ancienne' },
  { cle: 'jeu-recent', libelle: 'Jeu le plus récent' },
  { cle: 'jeu-ancien', libelle: 'Jeu le plus ancien' },
  { cle: 'titre-az', libelle: 'Titre de A à Z' },
  { cle: 'titre-za', libelle: 'Titre de Z à A' },
  { cle: 'note', libelle: 'Meilleure note' },
];

// Compare deux dates ISO ; une date manquante passe toujours en dernier
function comparerDates(a, b, decroissant) {
  if (!a && !b) return 0;
  if (!a) return 1;
  if (!b) return -1;
  return decroissant ? b.localeCompare(a) : a.localeCompare(b);
}

const COMPARATEURS = {
  'review-recente': (a, b) => comparerDates(a.dateReview, b.dateReview, true),
  'review-ancienne': (a, b) => comparerDates(a.dateReview, b.dateReview, false),
  'jeu-recent': (a, b) => comparerDates(a.dateSortie, b.dateSortie, true),
  'jeu-ancien': (a, b) => comparerDates(a.dateSortie, b.dateSortie, false),
  'titre-az': (a, b) => a.titre.localeCompare(b.titre, 'fr'),
  'titre-za': (a, b) => b.titre.localeCompare(a.titre, 'fr'),
  note: (a, b) => {
    if (a.note === null && b.note === null) return 0;
    if (a.note === null) return 1;
    if (b.note === null) return -1;
    return b.note - a.note;
  },
};

// Rang de chaque jeu (par adresse) pour un tri donné ; Map vide pour l'ordre du site
export function classement(typeJeux, tri) {
  const comparer = COMPARATEURS[tri];
  const rangs = new Map();
  if (!comparer) return rangs;
  jeux
    .filter((jeu) => jeu.type === typeJeux)
    .slice()
    .sort(comparer)
    .forEach((jeu, index) => rangs.set(jeu.slug, index + 1));
  return rangs;
}

const CLE_PANNEAU = 'geekzone-filtres-ouverts';

function lirePanneauOuvert() {
  try {
    return sessionStorage.getItem(CLE_PANNEAU) === '1';
  } catch (e) {
    return false;
  }
}

export default {
  data() {
    return {
      searchQuery: '',
      filtres: filtresVides(),
      tri: '',
      filtresOuverts: lirePanneauOuvert(),
      hasResults: true,
    };
  },
  computed: {
    normalizedQuery() {
      return normaliser(this.searchQuery);
    },
    optionsFiltres() {
      return optionsPour(this.typeJeux);
    },
    rangs() {
      return classement(this.typeJeux, this.tri);
    },
    filtresActifs() {
      return this.nombreFiltresActifs > 0;
    },
    nombreFiltresActifs() {
      return Object.values(this.filtres).filter(Boolean).length;
    },
    libelleBoutonFiltres() {
      // Le nombre de filtres en cours reste visible quand le panneau est fermé
      return this.nombreFiltresActifs > 0 && !this.filtresOuverts
        ? `Filtres (${this.nombreFiltresActifs})`
        : 'Filtres';
    },
    showNoResults() {
      return (Boolean(this.normalizedQuery) || this.filtresActifs) && !this.hasResults;
    },
  },
  watch: {
    searchQuery() {
      this.$nextTick(() => this.updateHasResults());
    },
    filtres: {
      deep: true,
      handler() {
        this.$nextTick(() => this.updateHasResults());
      },
    },
  },
  mounted() {
    this.updateHasResults();
  },
  methods: {
    matches(name, slug) {
      const jeu = slug ? trouverJeu(slug) : null;
      if (!correspondAuxFiltres(jeu, this.filtres)) return false;
      if (!this.normalizedQuery) return true;
      const texte = `${normaliser(name)} ${texteRecherchable(jeu)}`;
      return texte.includes(this.normalizedQuery);
    },
    reinitialiserFiltres() {
      this.filtres = filtresVides();
      this.tri = '';
    },
    // Position d'une carte dans la grille selon le tri choisi (0 = ordre du code)
    ordreCarte(slug) {
      return this.rangs.get(slug) || 0;
    },
    basculerFiltres() {
      this.filtresOuverts = !this.filtresOuverts;
      try {
        sessionStorage.setItem(CLE_PANNEAU, this.filtresOuverts ? '1' : '0');
      } catch (e) {
        // stockage indisponible : le panneau ne sera juste pas mémorisé
      }
    },
    updateHasResults() {
      if (!this.$el || !this.$el.querySelectorAll) {
        this.hasResults = true;
        return;
      }
      const cards = Array.from(this.$el.querySelectorAll('.bordure-texte'));
      this.hasResults = cards.some((card) => card.style.display !== 'none');
    },
  },
};
