<template>
  <dl v-if="lignes.length" class="fiche">
    <div v-for="ligne in lignes" :key="ligne.libelle">
      <dt>{{ ligne.libelle }}</dt>
      <dd>{{ ligne.valeur }}</dd>
    </div>
  </dl>
</template>

<script>
import { trouverJeu, formaterDate } from '../data/jeux';

// Fiche technique d'une page de review ou de Let's Play, générée depuis src/data/jeux.js.
// Seuls les attributs renseignés sont affichés ; sans aucun attribut, la fiche est absente.
export default {
  name: 'FicheJeuComponent',
  computed: {
    jeu() {
      return trouverJeu(this.$route.path);
    },
    lignes() {
      const jeu = this.jeu || {};
      return [
        ['Plateformes', (jeu.plateformes || []).join(', ')],
        ['Date de sortie', jeu.dateSortie ? formaterDate(jeu.dateSortie) : ''],
        ['Développeur', jeu.developpeur],
        ['Éditeur', jeu.editeur],
        ['Genre', (jeu.genre || []).join(', ')],
        // Le type de jeu et le nombre de joueurs restent dans le filtre mais ne sont pas affichés ici
      ]
        .filter(([, valeur]) => valeur)
        .map(([libelle, valeur]) => ({ libelle, valeur }));
    },
  },
};
</script>
