<template>
  <p v-if="texte" class="date-review">{{ texte }}</p>
</template>

<script>
import { trouverJeu, formaterDate } from '../data/jeux';

// Affiche, en bas d'une page de review ou de Let's Play, la date de publication lue dans
// src/data/jeux.js. N'affiche rien si la page n'a pas d'entrée ou pas encore de date.
export default {
  name: 'ReviewDateComponent',
  computed: {
    texte() {
      const jeu = trouverJeu(this.$route.path);
      if (!jeu || !jeu.dateReview) return '';
      const libelle = jeu.type === 'letsplay' ? "Let’s Play publié le" : 'Review publiée le';
      return `${libelle} ${formaterDate(jeu.dateReview)}`;
    },
  },
};
</script>
