<template>
  <div class="menu-review">
    <div class="logo-review">
      <router-link to="/">
        <img
          src="../assets/Logo_Geek_Zone.png"
          alt="Logo de Geek Zone"
          class="image pc-only"
        />
      </router-link>
    </div>
    <h1>{{ pageTitle }}</h1>
    <nav>
      <ul>
        <li v-for="section in sections" :key="section.id">
          <router-link :to="`#${section.id}`">{{ section.titre }}</router-link>
        </li>
      </ul>
    </nav>
  </div>
</template>

<script>
import { lireSectionsDeLaPage } from '../utils/sectionsPage';

export default {
  name: 'MenuLetsPlayComponent',
  data() {
    return { sections: [] };
  },
  computed: {
    pageTitle() {
      return this.$route.meta.title;
    },
  },
  mounted() {
    this.rafraichirSections();
  },
  watch: {
    $route() {
      this.rafraichirSections();
    },
  },
  methods: {
    // Même principe que le menu des reviews : les liens suivent les sections de la page
    rafraichirSections() {
      this.$nextTick(() => {
        this.sections = lireSectionsDeLaPage();
      });
    },
  },
};
</script>
