// Directive v-fit-columns : dimensionne une liste de cartes (pages Review, Let's Play et Wishlist).
//
// - Le nombre de colonnes est le maximum qui tient avec des cartes d'au moins --card-min de large.
// - Les cartes s'élargissent pour remplir toute la largeur : quand une rangée perd une carte,
//   les cartes restantes grandissent, puis rétrécissent jusqu'au seuil suivant. Jamais de vide
//   sur les côtés.
// - S'il y a moins de cartes visibles que de colonnes possibles, la colonne se resserre sur les
//   cartes présentes (au plus --card-max chacune) et reste centrée.
// - La barre de recherche partage la même colonne, elle a donc toujours la largeur de la grille.

const SIDE_MARGIN = 40; // 20 px de chaque côté, comme dans Style.css

export function computeLayout({ available, cardMin, cardMax, gap, visible }) {
  if (!cardMin || !cardMax || available <= 0) return null;
  const columnsThatFit = Math.max(1, Math.floor((available + gap) / (cardMin + gap)));
  const columns = Math.max(1, Math.min(columnsThatFit, visible));
  // Le plafond --card-max ne joue que si c'est le nombre de cartes qui limite, pas la place :
  // quand la place limite, les cartes remplissent toute la largeur.
  const limitedByCount = visible < columnsThatFit;
  const width = limitedByCount ? Math.min(available, columns * cardMax + (columns - 1) * gap) : available;
  return { columns, width };
}

function fit(el) {
  const grid = el.querySelector('.team-member');
  const parent = el.parentElement;
  if (!grid || !parent) return;

  const styles = getComputedStyle(el);
  const cardMin = parseFloat(styles.getPropertyValue('--card-min'));
  const cardMax = parseFloat(styles.getPropertyValue('--card-max'));
  const gap = parseFloat(getComputedStyle(grid).columnGap) || 0;
  // v-show masque les cartes filtrées par un style en ligne : on lit ce style directement
  const visible = Array.from(grid.children).filter((card) => card.style.display !== 'none').length;
  const available = parent.clientWidth - SIDE_MARGIN;

  const layout = computeLayout({ available, cardMin, cardMax, gap, visible });
  if (!layout) {
    el.style.width = '';
    grid.style.gridTemplateColumns = '';
    return;
  }
  el.style.width = `${layout.width}px`;
  grid.style.gridTemplateColumns = `repeat(${layout.columns}, minmax(0, 1fr))`;
}

export default {
  mounted(el) {
    el.__fitColumns = () => fit(el);
    el.__fitColumns();
    window.addEventListener('resize', el.__fitColumns);
  },
  updated(el) {
    fit(el);
  },
  unmounted(el) {
    window.removeEventListener('resize', el.__fitColumns);
    delete el.__fitColumns;
  },
};
